const int MAXN = 16;
int a[MAXN], tree[MAXN * 4], tag[MAXN * 4];

void build(int o, int l, int r) {
  if (l == r) { tree[o] = a[l]; return; }
  int mid = (l + r) / 2;
  build(o * 2, l, mid);
  build(o * 2 + 1, mid + 1, r);
  tree[o] = tree[o * 2] + tree[o * 2 + 1];
}

void apply(int o, int l, int r, int v) {
  tree[o] += v * (r - l + 1);
  tag[o] += v;
}

void pushdown(int o, int l, int r) {
  if (tag[o] == 0) return;
  int mid = (l + r) / 2;
  apply(o * 2, l, mid, tag[o]);
  apply(o * 2 + 1, mid + 1, r, tag[o]);
  tag[o] = 0;
}

void rangeAdd(int o, int l, int r, int ql, int qr, int v) {
  if (ql <= l && r <= qr) { apply(o, l, r, v); return; }
  pushdown(o, l, r);
  int mid = (l + r) / 2;
  if (ql <= mid) rangeAdd(o * 2, l, mid, ql, qr, v);
  if (qr > mid) rangeAdd(o * 2 + 1, mid + 1, r, ql, qr, v);
  tree[o] = tree[o * 2] + tree[o * 2 + 1];
}

int rangeSum(int o, int l, int r, int ql, int qr) {
  if (ql <= l && r <= qr) return tree[o];
  pushdown(o, l, r);
  int mid = (l + r) / 2, s = 0;
  if (ql <= mid) s += rangeSum(o * 2, l, mid, ql, qr);
  if (qr > mid) s += rangeSum(o * 2 + 1, mid + 1, r, ql, qr);
  return s;
}

