vector<long long> tmp(t);
sort(tmp.begin(), tmp.end());
tmp.erase(unique(tmp.begin(), tmp.end()), tmp.end());
vector<int> id(n);
for (int i = 0; i < n; i++)
    id[i] = (int)(lower_bound(tmp.begin(), tmp.end(), t[i]) - tmp.begin()) + 1;
sort(id.begin(), id.end());
long long gap = LLONG_MAX;
for (int i = 1; i < n; i++)
    if (id[i] != id[i - 1])                                // 名次不同才是不同时刻
        gap = min(gap, tmp[id[i] - 1] - tmp[id[i - 1] - 1]);  // 名次映射回原值再作差
